#include <Arduino.h>

constexpr uint8_t LED_PIN = 9;   // ATmega328P: PWM über Timer1
constexpr uint8_t BUTTON_PIN = 2;
constexpr uint32_t STATUS_MS = 1000U;

bool active = false;
uint32_t deactivate_at_ms = 0U;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
}

void loop() {
  const uint32_t now = millis(); // Arduino-Zeitbasis: typischerweise Timer0

  if (digitalRead(BUTTON_PIN) == LOW) {
    active = true;
    deactivate_at_ms = now + STATUS_MS;
  }

  if (active && (int32_t)(now - deactivate_at_ms) >= 0) {
    active = false;
  }

  analogWrite(LED_PIN, active ? 160 : 0); // Pin 9 nutzt Timer1-PWM
}

#include <Arduino.h>
#include <avr/interrupt.h>

constexpr uint8_t LED_PIN = 13;
static volatile uint16_t pending_ms = 0U;

ISR(TIMER1_COMPA_vect) {
  if (pending_ms < UINT16_MAX) {
    pending_ms++;
  }
}

static void configure_timer1_ctc_1khz() {
  cli();
  TCCR1A = 0U;
  TCCR1B = _BV(WGM12) | _BV(CS11) | _BV(CS10);
  OCR1A = 249U; // 16 MHz / 64 / (249 + 1) = 1 kHz
  TIMSK1 = _BV(OCIE1A);
  sei();
}

void setup() {
  pinMode(LED_PIN, OUTPUT);
  configure_timer1_ctc_1khz();
  // Timer1 gehört jetzt der Anwendung: kein analogWrite an Pin 9/10,
  // keine Servo-Bibliothek ohne erneute Ressourcenentscheidung.
}

void loop() {
  uint16_t elapsed = 0U;
  cli();
  elapsed = pending_ms;
  pending_ms = 0U;
  sei();

  while (elapsed-- > 0U) {
    update_status_one_millisecond();
  }
  digitalWrite(LED_PIN, status_is_active() ? HIGH : LOW);
}

#include <avr/io.h>
#include <avr/interrupt.h>
#include <stdint.h>

static volatile uint16_t pending_ms = 0U;

ISR(TIMER1_COMPA_vect) {
  if (pending_ms < UINT16_MAX) {
    pending_ms++;
  }
}

static void gpio_init(void) {
  DDRB |= _BV(DDB5);   // Nano/Uno LED an PB5
  PORTB &= (uint8_t)~_BV(PORTB5);
}

static void timer1_init(void) {
  TCCR1A = 0U;
  TCCR1B = _BV(WGM12) | _BV(CS11) | _BV(CS10);
  OCR1A = 249U;
  TIMSK1 = _BV(OCIE1A);
}

int main(void) {
  gpio_init();
  timer1_init();
  sei();

  for (;;) {
    uint16_t elapsed;
    cli();
    elapsed = pending_ms;
    pending_ms = 0U;
    sei();

    while (elapsed-- > 0U) {
      update_status_one_millisecond();
    }

    if (status_is_active()) PORTB |= _BV(PORTB5);
    else PORTB &= (uint8_t)~_BV(PORTB5);
  }
}
